import{_ as l,a0 as r,w as o,s as d,ao as t,I as p,x as a,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"初次登錄 Linux 服務器馬上要做的 9 件事 | LCTT x X-CMD","titleTemplate":false,"description":"初次登錄 Linux 服務器馬上要做的 9 件事 | LCTT (202012) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"初次登錄 Linux 服務器馬上要做的 9 件事 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"初次登錄 Linux 服務器馬上要做的 9 件事 | LCTT (202012) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202012/20201215 9 things to do in your first 10 minutes on a Linux server","title":"初次登錄 Linux 服務器馬上要做的 9 件事","tag":"202012","desc":""},"relativePath":"202012/20201215 9 things to do in your first 10 minutes on a Linux server.md","filePath":"[post].md"}'),h={name:"202012/20201215 9 things to do in your first 10 minutes on a Linux server.md"};function c(u,s,g,k,b,m){const n=r("Link");return o(),d("div",null,[s[18]||(s[18]=t(`<h1 id="初次登錄-linux-服務器馬上要做的-9-件事" tabindex="-1">初次登錄 Linux 服務器馬上要做的 9 件事 <a class="header-anchor" href="#初次登錄-linux-服務器馬上要做的-9-件事" aria-label="Permalink to “初次登錄 Linux 服務器馬上要做的 9 件事”">​</a></h1><blockquote><p>在將新配置的服務器投入工作之前，請確保你知道你正在使用什麼。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202012/27/112042zuz1lpudkypeppeu.jpg" alt=""></p><p>當我在 Linux 上測試軟件時（這是我工作中的一個常規部分），我需要使用多台運行 Linux 的不同架構的服務器。我整備機器，安裝所需的軟件包，運行我的測試，收集結果，並將機器返回到倉庫中，以便其他人可以使用它進行測試。</p><p>由於我經常這樣做（甚至一天多次），我初次登錄 Linux 服務器的前 10 分鐘內的工作已經成為每天的儀式。當我初次登錄 Linux 服務器時，我會使用命令來收集我需要的信息來尋找某些東西。我將在本文中介紹我的過程，但請注意，在大多數情況下，我只給出命令名稱，所以你需要確定這些命令的具體選項，以獲得你需要的信息。閲讀命令的手冊頁是一個很好的起點。</p><h3 id="_1、第一次接觸" tabindex="-1">1、第一次接觸 <a class="header-anchor" href="#_1、第一次接觸" aria-label="Permalink to “1、第一次接觸”">​</a></h3><p>當我登錄到一台服務器時，我做的第一件事就是檢查它是否擁有我將要運行的測試所需的操作系統、內核和硬件架構。我經常會檢查一台服務器已經運行了多久。雖然這對測試系統來説並不重要，因為它會被多次重啓，但我還是發現這些信息很有幫助。</p><p>使用下面的命令來獲取這些信息。我主要使用 Red Hat Linux 進行測試，所以如果你使用其他 Linux 發行版，請在文件名中使用 <code>*-release</code> 而不是 <code>redhat-release</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat /etc/redhat-release</span></span>
<span class="line"><span>uname -a</span></span>
<span class="line"><span>hostnamectl</span></span>
<span class="line"><span>uptime</span></span></code></pre></div><h3 id="_2、有人登錄在上面嗎" tabindex="-1">2、有人登錄在上面嗎？ <a class="header-anchor" href="#_2、有人登錄在上面嗎" aria-label="Permalink to “2、有人登錄在上面嗎？”">​</a></h3><p>一旦我知道這台機器符合我的測試需求，我需要確保沒有其他人同時登錄該系統運行他們自己的測試。雖然考慮到整備系統會幫我處理好這個問題，這種可能性很小，但偶爾檢查一下還是有好處的 —— 尤其是當我第一次登錄服務器的時候。我還會檢查是否有其他用户（除了 root）可以訪問系統。</p><p>使用下面的命令來查找這些信息。最後一條命令是查找 <code>/etc/passwd</code> 文件中具有 shell 訪問權限的用户；它會跳過文件中沒有 shell 訪問權限或 shell 設置為 <code>nologin</code> 的其他服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>who</span></span>
<span class="line"><span>who -Hu</span></span>
<span class="line"><span>grep sh$ /etc/passwd</span></span></code></pre></div><h3 id="_3、物理機還是虛擬機" tabindex="-1">3、物理機還是虛擬機 <a class="header-anchor" href="#_3、物理機還是虛擬機" aria-label="Permalink to “3、物理機還是虛擬機”">​</a></h3><p>現在我有了屬於自己的機器，我需要確定它是一台物理機還是一台虛擬機（VM）。如果是我自己整備的這台機器，我可以確定這是我要求的東西。但是，如果你使用的是一台不是你自己整備的機器，你應該檢查該機器是物理機還是虛擬機。</p><p>使用以下命令來識別這些信息。如果是物理系統，你會看到供應商的名稱（如 HP、IBM 等）以及服務器的品牌和型號；而在虛擬機中，你應該看到 KVM、VirtualBox 等，這取決於創建虛擬機時使用了什麼虛擬化軟件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dmidecode -s system-manufacturer</span></span>
<span class="line"><span>dmidecode -s system-product-name</span></span>
<span class="line"><span>lshw -c system | grep product | head -1</span></span>
<span class="line"><span>cat /sys/class/dmi/id/product_name</span></span>
<span class="line"><span>cat /sys/class/dmi/id/sys_vendor</span></span></code></pre></div><h3 id="_4、硬件" tabindex="-1">4、硬件 <a class="header-anchor" href="#_4、硬件" aria-label="Permalink to “4、硬件”">​</a></h3><p>因為我經常測試連接到 Linux 機器的硬件，所以我通常使用物理服務器，而不是虛擬機。在物理機器上，我的下一步是確定服務器的硬件能力 —— 例如，運行的是什麼類型的 CPU，它有多少個核心，啓用了哪些標誌，以及有多少內存可用於運行測試。如果我正在運行網絡測試，我會檢查連接到服務器的以太網或其他網絡設備的類型和容量。</p><p>使用以下命令來顯示連接到 Linux 服務器的硬件。其中一些命令在新的操作系統版本中可能會被廢棄，但你仍然可以從 yum 存儲庫中安裝它們或切換到它們的等效新命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lscpu or cat /proc/cpuinfo</span></span>
<span class="line"><span>lsmem or cat /proc/meminfo</span></span>
<span class="line"><span>ifconfig -a</span></span>
<span class="line"><span>ethtool &lt;devname&gt;</span></span>
<span class="line"><span>lshw</span></span>
<span class="line"><span>lspci</span></span>
<span class="line"><span>dmidecode</span></span></code></pre></div><h3 id="_5、已安裝的軟件" tabindex="-1">5、已安裝的軟件 <a class="header-anchor" href="#_5、已安裝的軟件" aria-label="Permalink to “5、已安裝的軟件”">​</a></h3><p>測試軟件總是需要安裝額外的依賴包、庫等。然而，在安裝任何東西之前，我都會檢查已經安裝了什麼（包括是什麼版本），以及配置了哪些存儲庫，這樣我就知道軟件來自哪裏，並可以調試任何軟件包安裝問題。</p><p>使用下面的命令來確定安裝了什麼軟件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rpm -qa</span></span>
<span class="line"><span>rpm -qa | grep &lt;pkgname&gt;</span></span>
<span class="line"><span>rpm -qi &lt;pkgname&gt;</span></span>
<span class="line"><span>yum repolist</span></span>
<span class="line"><span>yum repoinfo</span></span>
<span class="line"><span>yum install &lt;pkgname&gt;</span></span>
<span class="line"><span>ls -l /etc/yum.repos.d/</span></span></code></pre></div><h3 id="_6、運行的進程和服務" tabindex="-1">6、運行的進程和服務 <a class="header-anchor" href="#_6、運行的進程和服務" aria-label="Permalink to “6、運行的進程和服務”">​</a></h3><p>檢查了安裝的軟件之後，自然就會檢查系統上有哪些進程在運行。當在系統上運行性能測試時，這一點至關重要 —— 如果一個正在運行的進程、守護進程、測試軟件等佔用了大部分 CPU/RAM，那麼在運行測試之前停止該進程是有意義的。這也可以檢查測試所需的進程或守護進程是否已經啓動並運行。例如，如果測試需要 <code>httpd</code> 運行，那麼即使安裝了軟件包，啓動守護進程的服務也可能沒有運行。</p><p>使用以下命令來識別系統上正在運行的進程和已啓用的服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pstree -pa 1</span></span>
<span class="line"><span>ps -ef</span></span>
<span class="line"><span>ps auxf</span></span>
<span class="line"><span>systemctl</span></span></code></pre></div><h3 id="_7、網絡連接" tabindex="-1">7、網絡連接 <a class="header-anchor" href="#_7、網絡連接" aria-label="Permalink to “7、網絡連接”">​</a></h3><p>如今的機器網絡化程度很高，它們需要與網絡上的其他機器或服務進行通信。我會識別服務器上哪些端口是開放的，是否有到測試機器的任何網絡連接，是否啓用了防火牆，如果啓用了，是否屏蔽了任何端口，以及機器與哪些 DNS 服務器對話。</p><p>使用以下命令來識別網絡服務相關信息。如果一個過時的命令不可用，請從 yum 存儲庫中安裝它或使用等效的新命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>netstat -tulpn</span></span>
<span class="line"><span>netstat -anp</span></span>
<span class="line"><span>lsof -i</span></span>
<span class="line"><span>ss</span></span>
<span class="line"><span>iptables -L -n</span></span>
<span class="line"><span>cat /etc/resolv.conf</span></span></code></pre></div><h3 id="_8、內核" tabindex="-1">8、內核 <a class="header-anchor" href="#_8、內核" aria-label="Permalink to “8、內核”">​</a></h3>`,34)),p("p",null,[s[1]||(s[1]=a("在進行系統測試時，我發現瞭解內核相關的信息是很有幫助的，比如內核版本和加載了哪些內核模組。我還會列出任何",-1)),e(n,{href:"https://www.oreilly.com/library/view/red-hat-enterprise/9781785283550/ch10s05.html"},{default:i(()=>[...s[0]||(s[0]=[a("可調整的內核參數",-1)])]),_:1}),s[2]||(s[2]=a("以及它們的設置，並檢查啓動運行中的內核時使用的選項。",-1))]),s[19]||(s[19]=t(`<p>使用以下命令來識別這些信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>uname -r</span></span>
<span class="line"><span>cat /proc/cmdline</span></span>
<span class="line"><span>lsmod</span></span>
<span class="line"><span>modinfo &lt;module&gt;</span></span>
<span class="line"><span>sysctl -a</span></span>
<span class="line"><span>cat /boot/grub2/grub.cfg</span></span></code></pre></div><h3 id="_9、日誌" tabindex="-1">9、日誌 <a class="header-anchor" href="#_9、日誌" aria-label="Permalink to “9、日誌”">​</a></h3><p>現在，我已經對服務器有了很好的瞭解，包括安裝了哪些軟件，運行了哪些進程。還有一件事我無法逃避，那就是日誌文件 —— 我需要知道在哪裏可以查看不斷更新的信息。</p><p>使用以下命令查看系統的日誌：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dmesg</span></span>
<span class="line"><span>tail -f /var/log/messages</span></span>
<span class="line"><span>journalctl</span></span></code></pre></div><h3 id="接下來的步驟" tabindex="-1">接下來的步驟 <a class="header-anchor" href="#接下來的步驟" aria-label="Permalink to “接下來的步驟”">​</a></h3><p>雖然命令和實用程序會發生變化，但它們所顯示的基本信息大致不變。在你專注於掌握哪些命令之前，你需要對你要尋找的信息以及它屬於什麼類別有一個宏觀的看法。</p><p>由於 Linux 將大部分信息保存在文件中，這些命令基本上是從文件中讀取信息，並以一種易於理解的方式呈現出來。下一步的好做法是找出每個命令用來獲取信息顯示的文件。一個提示：尋找這些信息的方法是 <code>strace</code> 命令。</p><hr>`,10)),p("p",null,[s[4]||(s[4]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/20/12/linux-server"},{default:i(()=>[...s[3]||(s[3]=[a("https://opensource.com/article/20/12/linux-server",-1)])]),_:1})]),p("p",null,[s[9]||(s[9]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/gkamathe"},{default:i(()=>[...s[5]||(s[5]=[a("Gaurav Kamathe",-1)])]),_:1}),s[10]||(s[10]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[6]||(s[6]=[a("lujun9972",-1)])]),_:1}),s[11]||(s[11]=a(" 譯者：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[7]||(s[7]=[a("wxy",-1)])]),_:1}),s[12]||(s[12]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[8]||(s[8]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[15]||(s[15]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[14]||(s[14]=[a("Linux中國",-1)])]),_:1}),s[17]||(s[17]=a(" 榮譽推出",-1))])])}const _=l(h,[["render",c]]);export{y as __pageData,_ as default};
